import sys
import fitz  # PyMuPDF

def extract_text(pdf_path: str) -> str:
    """Open the PDF at *pdf_path* and return its extracted text."""
    doc = fitz.open(pdf_path)
    text = []
    for page in doc:
        text.append(page.get_text())
    doc.close()
    return "\n".join(text)

def main():
    if len(sys.argv) != 2:
        print("Usage: python main.py <pdf_path>")
        sys.exit(1)
